public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> res = new ArrayList<>();
    if (nums == null || nums.length == 0) {
        return res;
    }
    boolean[] used = new boolean[nums.length];
    List<Integer> current = new ArrayList<>();
    backtrack(nums, used, current, res);
    return res;
}

private void backtrack(int[] nums, boolean[] used, List<Integer> current, List<List<Integer>> res) {
    if (current.size() == nums.length) {
        res.add(new ArrayList<>(current));
        return;
    }
    for (int i = 0; i < nums.length; i++) {
        if (!used[i]) {
            used[i] = true;
            current.add(nums[i]);
            backtrack(nums, used, current, res);
            current.remove(current.size() - 1);
            used[i] = false;
        }
    }
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    // Determine the minimum length among all strings to bound the search
    int minLen = Integer.MAX_VALUE;
    for (String s : strings) {
        if (s == null) {
            s = "";
        }
        if (s.length() < minLen) {
            minLen = s.length();
        }
    }
    if (minLen == 0) {
        return 0;
    }
    // Use the first non-null string as the source of candidate substrings
    String first = null;
    for (String s : strings) {
        if (s != null) {
            first = s;
            break;
        }
    }
    if (first == null) {
        return 0;
    }
    // Iterate lengths from largest to smallest
    for (int len = minLen; len >= 1; len--) {
        // Use a set to avoid duplicate candidates
        java.util.HashSet<String> seen = new java.util.HashSet<>();
        for (int i = 0; i <= first.length() - len; i++) {
            String candidate = first.substring(i, i + len);
            if (!seen.add(candidate)) {
                continue; // already processed this candidate
            }
            String revCandidate = new StringBuilder(candidate).reverse().toString();
            boolean ok = true;
            for (String s : strings) {
                if (s == null) {
                    s = "";
                }
                if (!(s.contains(candidate) || s.contains(revCandidate))) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                return len;
            }
        }
    }
    return 0;
}

public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0) {
        return 0;
    }
    int rows = grid.length;
    int cols = 0;
    for (char[] row : grid) {
        if (row != null && row.length > cols) {
            cols = row.length;
        }
    }
    if (cols == 0) {
        return 0;
    }
    boolean[][] visited = new boolean[rows][cols];
    int deposits = 0;
    int[] dRow = {-1, -1, -1, 0, 0, 1, 1, 1};
    int[] dCol = {-1, 0, 1, -1, 1, -1, 0, 1};

    for (int r = 0; r < rows; r++) {
        if (grid[r] == null) continue;
        for (int c = 0; c < grid[r].length; c++) {
            if (grid[r][c] == '@' && !visited[r][c]) {
                deposits++;
                // BFS/DFS to mark all connected '@'
                java.util.ArrayDeque<int[]> stack = new java.util.ArrayDeque<>();
                stack.push(new int[]{r, c});
                visited[r][c] = true;
                while (!stack.isEmpty()) {
                    int[] pos = stack.pop();
                    int cr = pos[0];
                    int cc = pos[1];
                    for (int k = 0; k < 8; k++) {
                        int nr = cr + dRow[k];
                        int nc = cc + dCol[k];
                        if (nr >= 0 && nr < rows && nc >= 0 && nc < grid[nr].length) {
                            if (!visited[nr][nc] && grid[nr][nc] == '@') {
                                visited[nr][nc] = true;
                                stack.push(new int[]{nr, nc});
                            }
                        }
                    }
                }
            }
        }
    }
    return deposits;
}

