                        result += countN;
                    }
                } else {
                    result += countN;
                }
            }
        }
    }
    return result;
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Validate inputs
    if (n <= 0) {
        return "cannot be travelled";
    }
    if (start == null || end == null || start.length == 0 || end.length == 0) {
        return "cannot be travelled";
    }
    // Interpret start and end as node indices if possible
    int startNode = -1;
    int endNode = -1;
    try {
        startNode = start[0];
        endNode = end[0];
    } catch (Exception e) {
        return "cannot be travelled";
    }
    if (startNode < 0 || startNode >= n || endNode < 0 || endNode >= n) {
        return "cannot be travelled";
    }
    // Build adjacency list
    java.util.List<java.util.List<Integer>> adj = new java.util.ArrayList<>(n);
    for (int i = 0; i < n; i++) {
        adj.add(new java.util.ArrayList<>());
    }
    if (paths != null) {
        for (int[] edge : paths) {
            if (edge == null || edge.length < 2) continue;
            int u = edge[0];
            int v = edge[1];
            if (u < 0 || u >= n || v < 0 || v >= n) continue;
            adj.get(u).add(v);
            adj.get(v).add(u);
        }
    }
    // BFS to check connectivity
    boolean[] visited = new boolean[n];
    java.util.Queue<Integer> queue = new java.util.LinkedList<>();
    queue.offer(startNode);
    visited[startNode] = true;
    while (!queue.isEmpty()) {
        int cur = queue.poll();
        if (cur == endNode) {
            return "can be travelled";
        }
        for (int neighbor : adj.get(cur)) {
            if (!visited[neighbor]) {
                visited[neighbor] = true;
                queue.offer(neighbor);
            }
        }
    }
    return "cannot be travelled";
}

public static String convertDatesToWeekdays(String date) {
    if (date == null) {
        throw new IllegalArgumentException("Input date cannot be null");
    }
    String[] parts = date.trim().split("\\s+");
    if (parts.length != 3) {
        throw new IllegalArgumentException("Input must be in format 'MM dd yyyy'");
    }
    try {
        int month = Integer.parseInt(parts[0]);
        int day = Integer.parseInt(parts[1]);
        int year = Integer.parseInt(parts[2]);

        java.time.LocalDate localDate = java.time.LocalDate.of(year, month, day);
        java.time.DayOfWeek dayOfWeek = localDate.getDayOfWeek();
        java.time.Month monthEnum = java.time.Month.of(month);

        java.time.format.TextStyle textStyle = java.time.format.TextStyle.FULL;
        java.util.Locale locale = java.util.Locale.ENGLISH;

        String monthName = monthEnum.getDisplayName(textStyle, locale);
        String weekdayName = dayOfWeek.getDisplayName(textStyle, locale);

        return String.format("%s %d, %d is a %s", monthName, day, year, weekdayName);
    } catch (NumberFormatException | java.time.DateTimeException e) {
        throw new IllegalArgumentException("Invalid date format or value", e);
    }
}

public int[] twoSum(int[] nums, int target) {
    if (nums == null || nums.length < 2) {
        throw new IllegalArgumentException("Input array must contain at least two elements.");
    }
    java.util.HashMap<Integer, Integer> map = new java.util.HashMap<>();
    for (int i = 0; i < nums.length; i++) {
        int complement = target - nums[i];
        if (map.containsKey(complement)) {
            return new int[]{map.get(complement), i};
        }
        map.put(nums[i], i);
    }
    throw new IllegalStateException("No two sum solution found.");
}

public int search(int[] nums, int target) {
    if (nums == null || nums.length == 0) {
        return -1;
    }
    int left = 0;
    int right = nums.length - 1;
    while (left <= right) {
        int mid = left + (right - left) / 2;
        if (nums[mid] == target) {
            return mid;
        }
        // Determine which side is sorted
        if (nums[left] <= nums[mid]) { // left side is sorted
            if (target >= nums[left] && target < nums[mid]) {
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        } else { // right side is sorted
            if (target > nums[mid] && target <= nums[right]) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
    }
    return -1;
}

public double trimMean(int[] arr) {
