    }
    return sum / (double) remaining;
}

public boolean canArrange(int[] arr, int k) {
    // Validate input
    if (arr == null || k <= 0) {
        return false;
    }
    // If number of elements is odd, cannot form pairs
    if (arr.length % 2 != 0) {
        return false;
    }

    int[] count = new int[k];
    for (int num : arr) {
        int r = ((num % k) + k) % k; // handle negative numbers
        count[r]++;
    }

    // Remainder 0 must have even count
    if (count[0] % 2 != 0) {
        return false;
    }

    int limit = k / 2;
    for (int r = 1; r <= limit; r++) {
        if (r == k - r) { // when k is even and r == k/2
            if (count[r] % 2 != 0) {
                return false;
            }
        } else {
            if (count[r] != count[k - r]) {
                return false;
            }
        }
    }

    return true;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    if (n <= 0 || hasApple == null || hasApple.length != n) {
        return 0;
    }
    java.util.List<Integer>[] graph = new java.util.ArrayList[n];
    for (int i = 0; i < n; i++) {
        graph[i] = new java.util.ArrayList<>();
    }
    if (edges != null) {
        for (int[] edge : edges) {
            if (edge == null || edge.length < 2) continue;
            int u = edge[0];
            int v = edge[1];
            if (u < 0 || u >= n || v < 0 || v >= n) continue;
            graph[u].add(v);
            graph[v].add(u);
        }
    }
    boolean[] subtreeHasApple = new boolean[n];
    int total = 0;
    java.util.Stack<int[]> stack = new java.util.Stack<>();
    stack.push(new int[]{0, -1, 0});
    while (!stack.isEmpty()) {
        int[] cur = stack.pop();
        int node = cur[0];
        int parent = cur[1];
        int state = cur[2];
        if (state == 0) {
            stack.push(new int[]{node, parent, 1});
            for (int neighbor : graph[node]) {
                if (neighbor != parent) {
                    stack.push(new int[]{neighbor, node, 0});
                }
            }
        } else {
            boolean has = hasApple[node];
            for (int neighbor : graph[node]) {
                if (neighbor != parent && subtreeHasApple[neighbor]) {
                    has = true;
                    total += 2;
                }
            }
            subtreeHasApple[node] = has;
        }
    }
    return total;
}

public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return "";
    }
    int[] count = new int[26];
    for (char c : s.toCharArray()) {
        if (c < 'a' || c > 'z') {
            // If the string contains characters outside 'a'-'z', ignore them
            continue;
        }
        count[c - 'a']++;
    }
    StringBuilder sb = new StringBuilder(s.length());
    int remaining = s.length();
    while (remaining > 0) {
        // Ascending pass: pick smallest to largest
        for (int i = 0; i < 26 && remaining > 0; i++) {
            if (count[i] > 0) {
                sb.append((char) ('a' + i));
                count[i]--;
                remaining--;
            }
        }
        // Descending pass: pick largest to smallest
        for (int i = 25; i >= 0 && remaining > 0; i--) {
            if (count[i] > 0) {
                sb.append((char) ('a' + i));
                count[i]--;
                remaining--;
            }
        }
    }
    return sb.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    if (nums == null || nums.length < 2) {
        return false;
    }
    int n = nums.length;
    int totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }
    // Use DP: for each possible subset size k, store achievable sums
    @SuppressWarnings("unchecked")
    java.util.HashSet<Integer>[] sums = new java.util.HashSet[n + 1];
    for (int i = 0; i <= n; i++) {
        sums[i] = new java.util.HashSet<>();
    }
    sums[0].add(0);
    for (int num : nums) {
        // iterate k from current max down to 1 to avoid using the same element twice
        for (int k = n - 1; k >= 1; k--) {
            for (int prevSum : sums[k - 1]) {
                sums[k].add(prevSum + num);
            }
        }
    }
    // Check for any k where average can be matched
    for (int k = 1; k <= n / 2; k++) {
        if ((totalSum * k) % n != 0) {
            continue;
        }
        int target = (totalSum * k) / n;
        if (sums[k].contains(target)) {
            return true;
        }
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null) {
        throw new IllegalArgumentException("cost array cannot be null");
    }
    int n = cost.length;
    if (n == 0) {
        return 0;
    }
    // dp[0] = 0, dp[1] = 0
    int prev2 = 0; // cost to reach step i-2
    int prev1 = 0; // cost to reach step i-1
    for (int i = 2; i <= n; i++) {
        int costPrev1 = cost[i - 1];
        int costPrev2 = cost[i - 2];
        int curr = Math.min(prev1 + costPrev1, prev2 + costPrev2);
        prev2 = prev1;
        prev1 = curr;
    }
    return prev1;
}

public int uniqueMorseRepresentations(String[] words) {
    if (words == null || words.length == 0) {
        return 0;
    }
    String[] morse = {".-","-...","-.-.","-..",".","..-.","--.","....","..",
                      ".---","-.-",".-..","--","-.","---",".--.","--.-",".-.",
                      "...","-","..-","...-",".--","-..-","-.--","--.."};
    java.util.Set<String> set = new java.util.HashSet<>();
    for (String word : words) {
        if (word == null) {
            continue;
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < word.length(); i++) {
            char c = word.charAt(i);
            if (c >= 'a' && c <= 'z') {
                sb.append(morse[c - 'a']);
            } else if (c >= 'A' && c <= 'Z') {
                sb.append(morse[c - 'A']);
            } // ignore non-letter characters
        }
        set.add(sb.toString());
    }
    return set.size();
}

public boolean hasAllCodes(String s, int k) {
    // Validate input
    if (s == null || k <= 0 || s.length() < k) {
        return false;
    }
    // For practical reasons, limit k to 20 (2^20 = 1,048,576)
    // Larger k would require an infeasible amount of memory/time.
    if (k > 20) {
        return false;
    }
    int total = 1 << k;          // total number of possible binary strings of length k
    boolean[] seen = new boolean[total];
    int mask = 0;
    int seenCount = 0;
    int maskLimit = total - 1;   // to keep mask within k bits

    for (int i = 0; i < s.length(); i++) {
        // Build the current k-bit window
        mask = ((mask << 1) & maskLimit) | (s.charAt(i) - '0');
        if (i >= k - 1) {
            if (!seen[mask]) {
                seen[mask] = true;
                seenCount++;
                if (seenCount == total) {
                    return true; // all codes found early
                }
            }
        }
    }
    return seenCount == total;
}

