public int minInsertions(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int insertions = 0;
    int balance = 0; // number of unmatched '('
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            balance++;
        } else if (c == ')') {
            if (balance == 0) {
                // need an opening bracket before this ')'
                insertions++;
                balance++; // pretend we inserted '('
            }
            balance--; // match this ')'
        } else {
            // invalid character, ignore or throw exception
            // For robustness, we can skip it
        }
    }
    // any remaining unmatched '(' need a ')'
    insertions += balance;
    return insertions;
}

