public int maxAbsoluteSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    int currentMax = nums[0];
    int currentMin = nums[0];
    int globalMax = nums[0];
    int globalMin = nums[0];
    for (int i = 1; i < nums.length; i++) {
        int num = nums[i];
        currentMax = Math.max(num, currentMax + num);
        globalMax = Math.max(globalMax, currentMax);
        currentMin = Math.min(num, currentMin + num);
        globalMin = Math.min(globalMin, currentMin);
    }
    return Math.max(globalMax, -globalMin);
}

public int findMinFibonacciNumbers(int k) {
    if (k <= 0) {
        return 0;
    }
    java.util.ArrayList<Integer> fib = new java.util.ArrayList<>();
    fib.add(1);
    fib.add(1);
    while (true) {
        int sz = fib.size();
        int next = fib.get(sz - 1) + fib.get(sz - 2);
        if (next > k) {
            break;
        }
        fib.add(next);
    }
    int count = 0;
    int remaining = k;
    for (int i = fib.size() - 1; i >= 0; i--) {
        int f = fib.get(i);
        if (f <= remaining) {
            remaining -= f;
            count++;
            if (remaining == 0) {
                break;
            }
        }
    }
    return count;
}

public int kthFactor(int n, int k) {
    if (n <= 0 || k <= 0) {
        return -1;
    }
    java.util.List<Integer> factors = new java.util.ArrayList<>();
    int sqrt = (int) Math.sqrt(n);
    for (int i = 1; i <= sqrt; i++) {
        if (n % i == 0) {
            factors.add(i);
            int other = n / i;
            if (other != i) {
                factors.add(other);
            }
        }
    }
    java.util.Collections.sort(factors);
    if (k > factors.size()) {
        return -1;
    }
    return factors.get(k - 1);
}

public String makeGood(String s) {
