        return null;
    }
    StringBuilder stack = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        int len = stack.length();
        if (len > 0) {
            char last = stack.charAt(len - 1);
            if (last != c && Character.toLowerCase(last) == Character.toLowerCase(c)) {
                stack.deleteCharAt(len - 1);
                continue;
            }
        }
        stack.append(c);
    }
    return stack.toString();
}

public int maxUniqueSplit(String s) {
    if (s == null || s.length() == 0) {
        return 0;
    }
    int n = s.length();
    int maxCount = 0;
    int totalMasks = 1 << (n - 1); // number of ways to cut between characters
    for (int mask = 0; mask < totalMasks; mask++) {
        java.util.HashSet<String> seen = new java.util.HashSet<>();
        int start = 0;
        boolean valid = true;
        for (int i = 0; i < n - 1; i++) {
            if ((mask & (1 << i)) != 0) { // cut after position i
                String part = s.substring(start, i + 1);
                if (!seen.add(part)) {
                    valid = false;
                    break;
                }
                start = i + 1;
            }
        }
        if (!valid) {
            continue;
        }
        // add the last part
        String lastPart = s.substring(start);
        if (!seen.add(lastPart)) {
            continue;
        }
        int count = seen.size();
        if (count > maxCount) {
            maxCount = count;
        }
    }
    return maxCount;
}

