public String getSmallestString(int n, int k) {
    if (n <= 0) {
        return k == 0 ? "" : "";
    }
    long minSum = (long) n * 1;
    long maxSum = (long) n * 26;
    if (k < minSum || k > maxSum) {
        return "";
    }
    StringBuilder sb = new StringBuilder(n);
    long remainingK = k;
    for (int i = 0; i < n; i++) {
        int remainingPositions = n - i - 1;
        long maxRemaining = (long) remainingPositions * 26;
        long v = Math.max(1L, remainingK - maxRemaining);
        if (v > 26) v = 26; // safety check
        sb.append((char) ('a' + (int) v - 1));
        remainingK -= v;
    }
    return sb.toString();
}

