public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0] == null || mat[0].length == 0) {
        return 0;
    }
    int m = mat.length;
    int n = mat[0].length;
    int[][] dpH = new int[m][n]; // horizontal
    int[][] dpV = new int[m][n]; // vertical
    int[][] dpD = new int[m][n]; // diagonal (top-left to bottom-right)
    int[][] dpAD = new int[m][n]; // anti-diagonal (top-right to bottom-left)
    int maxLen = 0;
    for (int i = 0; i < m; i++) {
        if (mat[i] == null || mat[i].length != n) {
            // Non-rectangular row, treat as zeros
            continue;
        }
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                dpH[i][j] = (j > 0 ? dpH[i][j - 1] : 0) + 1;
                dpV[i][j] = (i > 0 ? dpV[i - 1][j] : 0) + 1;
                dpD[i][j] = (i > 0 && j > 0 ? dpD[i - 1][j - 1] : 0) + 1;
                dpAD[i][j] = (i > 0 && j < n - 1 ? dpAD[i - 1][j + 1] : 0) + 1;
                int localMax = Math.max(Math.max(dpH[i][j], dpV[i][j]),
                                        Math.max(dpD[i][j], dpAD[i][j]));
                if (localMax > maxLen) {
                    maxLen = localMax;
                }
            } else {
                dpH[i][j] = dpV[i][j] = dpD[i][j] = dpAD[i][j] = 0;
            }
        }
    }
    return maxLen;
}

public static String addThousandSeparator(int n) {
    // Handle negative numbers by preserving the sign and working with the absolute value
    boolean negative = n < 0;
    long value = n;
    if (negative) {
        value = -value; // safe in long even for Integer.MIN_VALUE
    }

    String numStr = Long.toString(value);
    int len = numStr.length();

    // Determine the size of the first group (may be less than 3)
    int firstGroup = len % 3;
    if (firstGroup == 0) {
        firstGroup = 3;
    }

    StringBuilder sb = new StringBuilder();
    sb.append(numStr.substring(0, firstGroup));

    // Append remaining groups, each preceded by a dot
    for (int i = firstGroup; i < len; i += 3) {
        sb.append('.');
        sb.append(numStr.substring(i, i + 3));
    }

    // Prepend the negative sign if needed
    return negative ? "-" + sb.toString() : sb.toString();
}

