public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }
    int n = heights.length;
    int[] stack = new int[n];
    int top = -1;
    long maxArea = 0;
    for (int i = 0; i < n; i++) {
        while (top >= 0 && heights[i] < heights[stack[top]]) {
            int height = heights[stack[top--]];
            int width = (top == -1) ? i : i - stack[top] - 1;
            long area = (long) height * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }
        stack[++top] = i;
    }
    while (top >= 0) {
        int height = heights[stack[top--]];
        int width = (top == -1) ? n : n - stack[top] - 1;
        long area = (long) height * width;
        if (area > maxArea) {
            maxArea = area;
        }
    }
    return (int) maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0] == null || mat[0].length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    int[] result = new int[m * n];
    int row = 0, col = 0;
    int direction = 0; // 0 = up-right, 1 = down-left
    for (int i = 0; i < m * n; i++) {
        result[i] = mat[row][col];
        if (direction == 0) { // moving up-right
            if (col == n - 1) { // hit last column
                row++;
                direction = 1;
            } else if (row == 0) { // hit first row
                col++;
                direction = 1;
            } else {
                row--;
                col++;
            }
        } else { // moving down-left
            if (row == m - 1) { // hit last row
                col++;
                direction = 0;
            } else if (col == 0) { // hit first column
                row++;
                direction = 0;
            } else {
                row++;
                col--;
            }
        }
    }
    return result;
}

